mapper.insert:
INSERT IGNORE INTO stock_news (
    stock_code, keyword, title, summary,
    origin_url, origin_url_hash,
    naver_link, publisher, published_at, collected_at
) VALUES (
    #{stockCode}, #{keyword}, #{title}, #{summary},
    #{originUrl}, #{originUrlHash},
    #{naverLink}, #{publisher}, #{publishedAt}, #{collectedAt}
)

mapper.select:
SELECT
    id, stock_code, keyword, title, summary,
    origin_url, origin_url_hash,
    naver_link, publisher, published_at, collected_at
FROM stock_news
WHERE stock_code = #{stockCode}
  AND published_at IS NOT NULL
  AND published_at >= #{since}
ORDER BY published_at DESC, collected_at DESC
LIMIT #{limit}
